// 자동 생성 — 직접 고치지 말 것. src/content/manual/*.md 를 고친 뒤 `npm run manual:build`(tests/manual/content.test.ts 가 어긋남을 잡는다).
export const MANUAL_SOURCES: readonly { file: string; raw: string }[] = [
  { file: "01-getting-started.md", raw: "---\ntitle: 시작하기\npart: start\naudience: member\nsummary: 로그인부터 화면 구성까지, D-Flow 를 처음 쓸 때 알아야 할 것을 설명합니다.\n---\n\n이 장은 D-Flow 를 처음 쓰는 분을 위한 안내입니다. 자세한 내용은 곧 채워집니다. 궁금한 점이 있으면 [자주 묻는 질문](/help/faq)을 먼저 보세요.\n\nD-Flow 는 팀이 함께 일의 계획을 세우고, 진행 상황을 기록하고, 그 결과를 모아서 보는 곳입니다. 처음에는 낯설 수 있지만, 한 번 로그인해서 화면을 둘러보면 금방 익숙해집니다. 서두르지 않고 한 단계씩 따라 하시면 됩니다.\n\n## 로그인하기\n\n1. 받은 초대 메일의 링크를 누르거나, 관리자에게 받은 주소로 들어갑니다.\n2. 이메일과 비밀번호를 넣고 로그인합니다.\n\n비밀번호가 기억나지 않으면 워크스페이스 관리자에게 다시 정해 달라고 요청하세요.\n\n## 화면 둘러보기\n\n로그인하면 첫 화면이 열립니다. 화면 왼쪽에는 자주 가는 곳으로 이동하는 메뉴가 있고, 가운데에는 지금 보고 있는 내용이 나옵니다. 메뉴에 보이지 않는 항목이 있다면, 관리자가 그 기능을 꺼 두었거나 내 권한으로는 쓸 수 없는 기능일 수 있습니다.\n" },
  { file: "90-faq.md", raw: "---\ntitle: 자주 묻는 질문\npart: help\naudience: member\nsummary: 자주 겪는 문제와 해결 방법을 모았습니다.\n---\n\n쓰다가 막히면 이 장을 먼저 보세요. 처음이라면 [시작하기](/help/getting-started#로그인하기)부터 읽어도 좋습니다.\n\n여기에는 많은 분이 비슷하게 겪은 일을 모아 두었습니다. 내용은 계속 늘어나며, 해결되지 않는 일이 있으면 아래 마지막 절의 안내대로 관리자에게 알려 주세요.\n\n## 화면이 이상하게 보여요\n\n브라우저를 새로 고쳐 보세요. 그래도 같으면 관리자에게 알려 주세요. 어떤 화면에서 무엇을 눌렀는지 함께 알려 주면 빨리 해결할 수 있습니다.\n\n## 메뉴가 보이지 않아요\n\n찾는 메뉴가 없다면 두 가지를 의심해 볼 수 있습니다. 하나는 관리자가 그 기능을 꺼 둔 경우이고, 다른 하나는 내 권한으로는 쓸 수 없는 기능인 경우입니다. 어느 쪽인지 모르겠으면 프로젝트 관리자에게 물어보세요.\n\n## 누구에게 물어봐야 하나요\n\n프로젝트 안의 일은 프로젝트 관리자에게, 계정이나 워크스페이스 전체에 관한 일은 워크스페이스 관리자에게 물어보세요.\n" },
]
